<?php
session_start();
header("X-Frame-Options: DENY"); header("X-Content-Type-Options: nosniff");
if(!isset($_SESSION['user_id']) || !isset($_SESSION['login_time'])){ header('Location: login.php'); exit; }
if(time() - $_SESSION['login_time'] > 3600){ session_destroy(); header('Location: login.php?timeout=1'); exit; }
$_SESSION['login_time']=time();
if(($_SESSION['role']??'')=='admin'){ header('Location: admin_dashboard.php'); exit; }
$data=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true); $uid=$_SESSION['user_id']; $my=[]; foreach($data['complaints'] as $c){ if($c['user_id']==$uid) $my[]=$c; }
$total=count($my); $pend=0; $prog=0; $res=0; foreach($my as $c){ $s=strtolower($c['status']); if($s=='pending')$pend++; if($s=='in progress')$prog++; if($s=='resolved'||$s=='closed')$res++; }
$myRev=array_reverse($my);
?>
